<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f6f7fb;
        --panel: rgba(255, 255, 255, 0.82);
        --panel-border: rgba(15, 23, 42, 0.08);
        --text: #0f172a;
        --muted: #475569;
        --accent: #6d5efc;
        --accent-soft: rgba(109, 94, 252, 0.12);
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
        --radius: 24px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(109, 94, 252, 0.18), transparent 30%),
          radial-gradient(circle at top right, rgba(56, 189, 248, 0.14), transparent 28%),
          var(--bg);
        color: var(--text);
        min-height: 100vh;
      }

      .app {
        width: min(960px, calc(100% - 32px));
        margin: 0 auto;
        padding: 56px 0 64px;
      }

      .hero {
        padding: 28px;
        border: 1px solid var(--panel-border);
        border-radius: calc(var(--radius) + 8px);
        background: var(--panel);
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
        margin-bottom: 24px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 18px 0 10px;
        font-size: clamp(2.4rem, 4vw, 4.2rem);
        line-height: 0.98;
        letter-spacing: -0.05em;
      }

      .lede {
        margin: 0;
        max-width: 62ch;
        color: var(--muted);
        font-size: 1.08rem;
        line-height: 1.7;
      }

      .faq {
        display: grid;
        gap: 14px;
      }

      .example {
        border: 1px solid var(--panel-border);
        border-radius: var(--radius);
        background: rgba(255, 255, 255, 0.88);
        box-shadow: 0 10px 30px rgba(15, 23, 42, 0.06);
        overflow: hidden;
      }

      .question {
        width: 100%;
        border: 0;
        background: transparent;
        padding: 22px 24px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        color: var(--text);
        font: inherit;
        font-weight: 700;
        text-align: left;
        cursor: pointer;
      }

      .question:hover {
        background: rgba(109, 94, 252, 0.05);
      }

      .question:focus-visible {
        outline: 3px solid rgba(109, 94, 252, 0.35);
        outline-offset: -3px;
      }

      .icon {
        flex: 0 0 auto;
        width: 30px;
        height: 30px;
        border-radius: 999px;
        display: grid;
        place-items: center;
        background: var(--accent-soft);
        color: var(--accent);
        transition: transform 0.2s ease, background 0.2s ease;
      }

      .example.is-open .icon {
        transform: rotate(45deg);
        background: rgba(109, 94, 252, 0.18);
      }

      .details {
        display: none;
        padding: 0 24px 22px;
        color: var(--muted);
        line-height: 1.75;
      }

      .example.is-open .details {
        display: block;
      }

      .details p {
        margin: 0;
      }

      @media (max-width: 640px) {
        .app {
          width: min(100% - 20px, 960px);
          padding: 18px 0 28px;
        }

        .hero,
        .question,
        .details {
          padding-left: 18px;
          padding-right: 18px;
        }

        .hero {
          padding-top: 22px;
          padding-bottom: 22px;
        }
      }
    </style>
  </head>
  <body>
    <main class="app" id="root"></main>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats purr when they are content, but they may also purr to soothe themselves when stressed, injured, or in pain. It is one of their most versatile forms of communication."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most cats sleep between 12 and 16 hours a day. Kittens and senior cats often sleep even more, which helps them conserve energy for short bursts of activity."
        },
        {
          question: "Why do cats knead with their paws?",
          answer:
            "Kneading is often a comfort behavior rooted in kittenhood. Adult cats may knead when relaxed, marking territory with scent glands in their paws or simply showing affection."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Cats thrive with stimulation such as climbing spaces, puzzle feeders, toys, and window perches. Enrichment helps prevent boredom and supports healthy behavior."
        },
        {
          question: "What should I feed a cat?",
          answer:
            "Cats are obligate carnivores, so they need a complete diet with animal-based protein, taurine, and essential nutrients. The best choice depends on age, health, and lifestyle, so a vet can help narrow it down."
        }
      ];

      function createHero() {
        const hero = document.createElement("section");
        hero.className = "hero";
        hero.innerHTML = `
          <div class="eyebrow">Cat FAQ</div>
          <h1>Answers for curious cat people.</h1>
          <p class="lede">
            A clean, modern FAQ page with expandable answers for quick browsing.
            Tap a question to reveal the details.
          </p>
        `;
        return hero;
      }

      function createFaqItem(item, index) {
        const wrapper = document.createElement("div");
        wrapper.className = "example";

        const button = document.createElement("button");
        button.className = "question";
        button.type = "button";
        button.setAttribute("aria-expanded", "false");
        button.setAttribute("aria-controls", `answer-${index}`);
        button.innerHTML = `<span>${item.question}</span><span class="icon" aria-hidden="true">+</span>`;

        const details = document.createElement("div");
        details.className = "details";
        details.id = `answer-${index}`;
        details.innerHTML = `<p>${item.answer}</p>`;

        button.addEventListener("click", () => {
          const expanded = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!expanded));
          wrapper.classList.toggle("is-open", !expanded);
        });

        wrapper.append(button, details);
        return wrapper;
      }

      function createFaqList(items) {
        const list = document.createElement("section");
        list.className = "faq";
        items.forEach((item, index) => {
          list.appendChild(createFaqItem(item, index));
        });
        return list;
      }

      function App() {
        const app = document.createElement("div");
        app.append(createHero(), createFaqList(faqs));
        return app;
      }

      document.getElementById("root").appendChild(App());
    </script>
  </body>
</html>
